<?php require __DIR__ . '/../../components/live-summary.php'; ?>
<div class="users-layout"><section class="panel"><div class="panel-heading"><h2>Usuarios</h2><span><?= count($users) ?> registros</span></div><div class="table-scroll"><table><caption class="sr-only">Usuarios de TiendaLab</caption><thead><tr><th>Nombre</th><th>Correo</th><th>Rol / estado</th><th>Acciones</th></tr></thead><tbody><?php foreach ($users as $u): ?><tr><td><b><?= e($u['nombre']) ?></b></td><td><?= e($u['correo']) ?></td><td><?= e($u['rol']) ?> · <?= $u['activo'] ? 'Activo' : 'Inactivo' ?></td><td><div class="table-actions"><a href="/admin-usuarios.php?editar=<?= e($u['id']) ?>">Editar</a><form method="post" action="/admin-usuarios.php" data-confirm="¿Eliminar este usuario? Si tiene referencias se desactivará."><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($u['id']) ?>"><button class="text-button danger" name="action" value="delete">Eliminar</button></form></div></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel form-panel"><form method="post" action="/admin-usuarios.php"><?= csrf_field() ?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= e($edit['id'] ?? 0) ?>"><h2><?= $edit ? 'Editar usuario' : 'Nuevo usuario' ?></h2><label for="user-name">Nombre</label><input id="user-name" name="nombre" required maxlength="100" value="<?= e($edit['nombre'] ?? '') ?>"><label for="user-email">Correo</label><input id="user-email" name="correo" type="email" required maxlength="190" value="<?= e($edit['correo'] ?? '') ?>"><label for="user-password">Contraseña <?= $edit ? '(opcional)' : '' ?></label><input id="user-password" name="password" type="password" minlength="12" maxlength="72" autocomplete="new-password" <?= !$edit ? 'required' : '' ?>><label for="user-role">Rol</label><select id="user-role" name="rol"><?php foreach (['comprador','vendedor','administrador'] as $r): ?><option value="<?= e($r) ?>" <?= ($edit['rol'] ?? 'comprador') === $r ? 'selected' : '' ?>><?= e(ucfirst($r)) ?></option><?php endforeach; ?></select><label for="user-active">Estado</label><select id="user-active" name="activo"><option value="1" <?= ($edit['activo'] ?? 1) ? 'selected' : '' ?>>Activo</option><option value="0" <?= isset($edit) && !$edit['activo'] ? 'selected' : '' ?>>Inactivo</option></select><p class="form-help">Las cuentas referenciadas por productos o facturas se desactivan al eliminar. No puedes quitarte tu propio acceso administrativo.</p><button class="wide"><?= $edit ? 'Guardar cambios' : 'Crear usuario' ?></button><a class="button secondary wide" href="/admin-usuarios.php">Nuevo usuario</a></form></section></div>
